 35→void ChatServer::onMessage(const TcpConnectionPtr& conn, Buffer* buffer) {
 36→    while (buffer->readableBytes() >= HEADER_SIZE) {
 37→        // 尝试解析消息
 38→        Message msg;
 39→        size_t parsed = Message::parse(buffer->peek(), buffer->readableBytes(), msg);
 40→        
 41→        if (parsed == 0) {
 42→            // 数据不足，等待更多数据
 43→            break;
 44→        } else if (parsed == static_cast<size_t>(-1)) {
 45→            // 协议错误，关闭连接
 46→            std::cerr << "[错误] 协议错误，关闭连接: " << conn->name() << std::endl;
 47→            conn->shutdown();
 48→            break;
 49→        }
 50→
 51→        // 消息解析成功，消费数据
 52→        buffer->retrieve(parsed);
 53→
 54→        // 处理消息
 55→        switch (msg.type) {
 56→            case MSG_LOGIN:
 57→                handleLogin(conn, msg.payload);
 58→                break;
 59→            case MSG_LOGOUT:
 60→                handleLogout(conn);
 61→                break;
 62→            case MSG_BROADCAST:
 63→                handleBroadcast(conn, msg.payload);
 64→                break;
 65→            case MSG_PRIVATE:
 66→                handlePrivate(conn, msg.payload);
 67→                break;
 68→            case MSG_USER_LIST:
 69→                sendUserList(conn);
 70→                break;
 71→            default:
 72→                std::cerr << "[警告] 未知消息类型: " << static_cast<int>(msg.type) << std::endl;
 73→                break;
 74→        }
