128→void ChatServer::handleBroadcast(const TcpConnectionPtr& conn, const std::string& message) {
129→    if (!conn->hasUsername()) {
130→        conn->send(makeError("请先登录"));
131→        return;
132→    }
133→
134→    // 构造广播消息
135→    std::string fullMessage = "[" + conn->username() + "]: " + message;
136→    std::cout << "[广播] " << fullMessage << std::endl;
137→    
138→    broadcastToAll(makeBroadcast(fullMessage));
