141→void ChatServer::handlePrivate(const TcpConnectionPtr& conn, const std::string& payload) {
142→    if (!conn->hasUsername()) {
143→        conn->send(makeError("请先登录"));
144→        return;
145→    }
146→
147→    // 解析私聊消息: target\0message
148→    size_t pos = payload.find('\0');
149→    if (pos == std::string::npos) {
150→        conn->send(makeError("私聊消息格式错误"));
151→        return;
152→    }
153→
154→    std::string target = payload.substr(0, pos);
155→    std::string message = payload.substr(pos + 1);
156→
157→    // 构造私聊消息
158→    std::string fullMessage = "[" + conn->username() + " 私聊]: " + message;
159→    std::cout << "[私聊] " << conn->username() << " -> " << target << ": " << message << std::endl;
160→
161→    if (sendToUser(target, makeBroadcast(fullMessage))) {
162→        // 发送成功，给发送者确认
163→        conn->send(makeSystem("私聊消息已发送给 " + target));
164→    } else {
165→        conn->send(makeError("用户 " + target + " 不在线"));
166→    }
167→}
