179→    std::string data = msg.serialize();
180→    
181→    std::lock_guard<std::mutex> lock(usersMutex_);
182→    for (auto& pair : users_) {
183→        if (pair.second != exclude) {
184→            pair.second->send(data);
185→        }
186→    }
