189→bool ChatServer::sendToUser(const std::string& username, const Message& msg) {
190→    std::lock_guard<std::mutex> lock(usersMutex_);
191→    auto it = users_.find(username);
192→    if (it != users_.end()) {
193→        it->second->send(msg);
194→        return true;
195→    }
196→    return false;
