 10→// 消息类型定义
 11→enum MessageType : uint8_t {
 12→    MSG_LOGIN     = 1,  // 登录请求 (payload: username)
 13→    MSG_LOGOUT    = 2,  // 登出请求
 14→    MSG_BROADCAST = 3,  // 广播消息 (payload: message)
 15→    MSG_PRIVATE   = 4,  // 私聊消息 (payload: target_user\0message)
 16→    MSG_USER_LIST = 5,  // 用户列表响应 (payload: user1\nuser2\n...)
 17→    MSG_SYSTEM    = 6,  // 系统通知 (payload: notification)
 18→    MSG_ERROR     = 7,  // 错误响应 (payload: error_message)
 19→    MSG_LOGIN_OK  = 8,  // 登录成功
 20→};
 21→
 22→// 消息头部大小: 4字节长度 + 1字节类型 = 5字节
 23→constexpr size_t HEADER_SIZE = 5;
 24→constexpr size_t MAX_PAYLOAD_SIZE = 4096;
 25→constexpr size_t MAX_MESSAGE_SIZE = HEADER_SIZE + MAX_PAYLOAD_SIZE;
 26→
 27→// 消息结构体
 28→struct Message {
 29→    MessageType type;
 30→    std::string payload;
 31→    
 32→    // 序列化为二进制
 33→    std::string serialize() const {
 34→        uint32_t length = static_cast<uint32_t>(payload.size() + 1); // +1 for type byte
 35→        std::string data(HEADER_SIZE + payload.size(), '\0');
 36→        
 37→        // 写入长度 (网络字节序)
 38→        data[0] = static_cast<char>((length >> 24) & 0xFF);
 39→        data[1] = static_cast<char>((length >> 16) & 0xFF);
 40→        data[2] = static_cast<char>((length >> 8) & 0xFF);
 41→        data[3] = static_cast<char>(length & 0xFF);
 42→        
 43→        // 写入类型
 44→        data[4] = static_cast<char>(type);
 45→        
 46→        // 写入负载
 47→        if (!payload.empty()) {
 48→            std::memcpy(&data[5], payload.data(), payload.size());
 49→        }
 50→        
 51→        return data;
 52→    }
 53→    
 54→    // 从缓冲区尝试解析消息，返回解析的字节数（0表示数据不足）
 55→    static size_t parse(const char* data, size_t len, Message& msg) {
 56→        if (len < HEADER_SIZE) return 0;
 57→        
 58→        // 读取长度
 59→        uint32_t length = (static_cast<uint8_t>(data[0]) << 24) |
 60→                          (static_cast<uint8_t>(data[1]) << 16) |
 61→                          (static_cast<uint8_t>(data[2]) << 8) |
 62→                          static_cast<uint8_t>(data[3]);
 63→        
 64→        // 检查长度是否合法
 65→        if (length > MAX_PAYLOAD_SIZE + 1) {
 66→            return static_cast<size_t>(-1); // 协议错误
 67→        }
 68→        
 69→        // 检查数据是否足够
 70→        size_t total = HEADER_SIZE + length - 1; // length 包含 type 字节
 71→        if (len < total) return 0;
 72→        
 73→        // 解析消息
 74→        msg.type = static_cast<MessageType>(data[4]);
 75→        msg.payload.assign(data + 5, length - 1);
 76→        
 77→        return total;
 78→    }
 79→};
 80→
