 71→void TcpConnection::handleRead() {
 72→    int savedErrno = 0;
 73→    ssize_t n = inputBuffer_.readFd(fd_, &savedErrno);
 74→
 75→    if (n > 0) {
 76→        // 有数据可读
 77→        if (messageCallback_) {
 78→            messageCallback_(shared_from_this(), &inputBuffer_);
 79→        }
 80→    } else if (n == 0) {
 81→        // 对端关闭连接
 82→        handleClose();
 83→    } else {
 84→        errno = savedErrno;
 85→        std::cerr << "TcpConnection::handleRead error: " << strerror(errno) << std::endl;
 86→        handleError();
 87→    }
