 92→        ssize_t n = outputBuffer_.writeFd(fd_, nullptr);
 93→        if (n > 0) {
 94→            if (outputBuffer_.readableBytes() == 0) {
 95→                // 数据发送完毕
 96→                channel_->disableWriting();
 97→                if (writeCompleteCallback_) {
 98→                    writeCompleteCallback_(shared_from_this());
 99→                }
100→                if (state_ == kDisconnecting) {
101→                    shutdownInLoop();
102→                }
103→            }
104→        } else {
