132→void TcpConnection::sendInLoop(const std::string& message) {
133→    ssize_t nwrote = 0;
134→    size_t remaining = message.size();
135→
136→    // 如果输出缓冲区为空，尝试直接写入
137→    if (outputBuffer_.readableBytes() == 0 && channel_->isWriting() == false) {
138→        nwrote = ::write(fd_, message.data(), message.size());
139→        if (nwrote >= 0) {
140→            remaining = message.size() - nwrote;
141→            if (remaining == 0 && writeCompleteCallback_) {
142→                writeCompleteCallback_(shared_from_this());
143→            }
144→        } else {
145→            nwrote = 0;
146→            if (errno != EWOULDBLOCK) {
147→                std::cerr << "TcpConnection::sendInLoop write error: " << strerror(errno) << std::endl;
148→                if (errno == EPIPE || errno == ECONNRESET) {
149→                    return;
150→                }
151→            }
152→        }
153→    }
154→
155→    // 如果还有数据未发送，加入输出缓冲区
156→    if (remaining > 0) {
157→        outputBuffer_.append(message.data() + nwrote, remaining);
158→        if (!channel_->isWriting()) {
159→            channel_->enableWriting();
160→        }
161→    }
162→}
